CREATE TABLE users (
  id BIGINT PRIMARY KEY,
  email TEXT UNIQUE NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE orders (
  id BIGINT PRIMARY KEY,
  user_id BIGINT NOT NULL REFERENCES users(id),
  total_cents INT NOT NULL CHECK (total_cents >= 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_orders_user_time
  ON orders (user_id, created_at DESC);

-- The read path this schema is built for:
SELECT o.id, o.total_cents
FROM orders o
WHERE o.user_id = 42
ORDER BY o.created_at DESC
LIMIT 20;

# Same facts, different model: document + key-value thinking
# Key is user id, value is a self-contained profile document.
# Fast to read whole profile, expensive to query across profiles.
user_profile = {
    "_id": "user:42",
    "email": "a@example.com",
    "recent_orders": [
        {"id": 101, "total_cents": 2999},
        {"id": 98, "total_cents": 499}
    ]
}
# KV lookup: O(1) by key, no join. Trade-off: no efficient
# query for "all orders over $50 last week" without a second index.
